// ============================================================================
// Program:      EECS 348 Assignment 4 - Sudoku Solver
// Description:  Object-oriented, recursive brute-force (depth-first search with
//               backtracking) Sudoku solver. Finds ALL solutions to a puzzle.
// Inputs:       puzzle1.txt ... puzzle5.txt (9 rows of 9 tokens; '_' = blank)
// Output:       For each file: the file name, the puzzle, and every solution
//               found (or "No solution found").
// Collaborators: None
// Other sources: Generated by Claude (Anthropic) from the assignment text
// Author:       Jun Brewer
// Creation date: October 16, 2026
// ============================================================================

#include <fstream>   // std::ifstream for reading puzzle files
#include <iostream>  // std::cout for output
#include <string>    // std::string for file names
#include <vector>    // std::vector to hold solutions

// ----------------------------------------------------------------------------
// Class: Board
// Holds a 9x9 grid and knows how to check, read, and print itself.
// ----------------------------------------------------------------------------
class Board {
public:
    static const int N = 9;      // grid dimension
    static const int BLOCK = 3;  // block dimension

    // Start with every cell empty (0 means blank)
    Board() {
        for (int r = 0; r < N; ++r) // repeat for every row
            for (int c = 0; c < N; ++c) // repeat for every column
                cells[r][c] = 0; // assign 0 to each cell
    }

    // Read a puzzle from a file; returns false if the file cannot be read
    bool load(const std::string& fileName) {
        std::ifstream in(fileName.c_str());  // open the file
        if (!in) return false;               // report failure to caller
        for (int r = 0; r < N; ++r) {        // repeat for every row
            for (int c = 0; c < N; ++c) {    // repeat for every column
                std::string token;           // each cell is one token
                if (!(in >> token)) return false;  // file too short
                // '_' is a blank (stored as 0); a digit is stored as its value
                cells[r][c] = (token[0] == '_') ? 0 : (token[0] - '0');
            }
        }
        return true; // load success
    }

    // Read-only access to a cell
    int get(int r, int c) const { return cells[r][c]; }

    // Write a value into a cell (0 clears it)
    void set(int r, int c, int value) { cells[r][c] = value; }

    // Can 'value' legally go in (r, c)? Checks row, column and 3x3 block.
    bool isValid(int r, int c, int value) const {
        for (int i = 0; i < N; ++i) { // repeat N times
            if (cells[r][i] == value) return false;  // same row
            if (cells[i][c] == value) return false;  // same column
        }
        int br = (r / BLOCK) * BLOCK;  // top row of this block
        int bc = (c / BLOCK) * BLOCK;  // left column of this block
        for (int i = 0; i < BLOCK; ++i) // repeat for every row in block
            for (int j = 0; j < BLOCK; ++j) // repeat for every column in block
                if (cells[br + i][bc + j] == value) return false;  // same block
        return true;
    }

    // Verify the starting clues do not already break a rule
    bool cluesAreConsistent() {
        for (int r = 0; r < N; ++r) { // repeat for every row 
            for (int c = 0; c < N; ++c) { // repeat for every column
                int v = cells[r][c]; // value that is being checked
                if (v == 0) continue; // skip if value is empty
                cells[r][c] = 0;                   // temporarily remove the clue
                bool ok = isValid(r, c, v);        // is it legal without itself?
                cells[r][c] = v;                   // put it back
                if (!ok) return false; // clues are not consistant. Not legal
            }
        }
        return true; // clues are consistant. legal
    }

    // Find the first empty cell in row-major order; false if grid is full
    bool findEmpty(int& r, int& c) const {
        for (r = 0; r < N; ++r) // repeat for every row in puzzle
            for (c = 0; c < N; ++c) // repeat for every column in puzzle
                if (cells[r][c] == 0) return true; // if empty(0) return true
        return false; // otherwise false
    }

    // Print the grid, digits separated by spaces, '_' for blanks
    void print() const {
        for (int r = 0; r < N; ++r) { // repeat for every row in puzzle
            for (int c = 0; c < N; ++c) { // repeat for every column in puzzle
                if (cells[r][c] == 0) std::cout << "_ "; // if value is 0, output "_" instead
                else std::cout << cells[r][c] << " "; // otherwise just ouput the number
            }
            std::cout << "\n";
        }
    }

private:
    int cells[N][N];  // 0 = empty, 1-9 = digit
};

// ----------------------------------------------------------------------------
// Class: SudokuSolver
// Recursive depth-first search with backtracking. Collects every solution.
// ----------------------------------------------------------------------------
class SudokuSolver {
public:
    // Solve a copy of the puzzle and remember all solutions found
    void solve(const Board& puzzle) {
        solutions.clear();               // forget earlier results
        Board working = puzzle;          // work on a copy
        if (!working.cluesAreConsistent()) return;  // contradictory clues
        search(working);                 // start the recursion
    }

    // Access the solutions found by the last call to solve()
    const std::vector<Board>& getSolutions() const { return solutions; }

private:
    std::vector<Board> solutions;  // every completed grid discovered

    // Recursive step: fill the next empty cell with each legal candidate
    void search(Board& board) {
        int r, c;
        if (!board.findEmpty(r, c)) {    // no empty cell: grid is complete
            solutions.push_back(board);  // save this solution
            return;
        }
        for (int value = 1; value <= 9; ++value) {  // try each candidate
            if (board.isValid(r, c, value)) {
                board.set(r, c, value);  // place candidate
                search(board);           // recurse with k+1 cells filled
                board.set(r, c, 0);      // backtrack: undo and try the next
            }
        }
    }
};

// ----------------------------------------------------------------------------
// Class: PuzzleRunner
// Loads each puzzle file, runs the solver, and reports the results.
// ----------------------------------------------------------------------------
class PuzzleRunner {
public:
    // Process one puzzle file and print everything required
    void run(const std::string& fileName) {
        std::cout << "File: " << fileName << "\n"; // get file input
        Board puzzle; // make Board object puzzle
        if (!puzzle.load(fileName)) { // failed to read puzzle
            std::cout << "Could not read puzzle file\n\n"; // error message
            return; // end program
        }
        std::cout << "Puzzle:\n"; // display the orgianl puzzle
        puzzle.print(); // display the orgianl puzzle

        SudokuSolver solver; // create SudokuSolver object solver
        solver.solve(puzzle); // sovle puzzle 
        const std::vector<Board>& found = solver.getSolutions(); // store solutions (vector) to found

        if (found.empty()) { // if no solution found
            std::cout << "\nNo solution found\n"; // error message
        } else { // solution found
            for (size_t i = 0; i < found.size(); ++i) { // for every solution found
                std::cout << "\nSolution " << (i + 1) << ":\n"; // numbers the solutions found
                found[i].print(); // ouputs that solution
            }
            std::cout << "\nSolutions found: " << found.size() << "\n"; // display total number of solutions found
        }
        std::cout << "\n"; // end with newline for readability
    }

    // Process puzzle1.txt through puzzle5.txt
    void runAll() {
        for (int i = 1; i <= 5; ++i) // loops 5 times (once for every puzzle)
            run("puzzle" + std::to_string(i) + ".txt"); // run method. only works if the files are named with the same convention
    }
};

// Entry point: create a runner object and let it do the work
int main() {
    PuzzleRunner runner; // creates PuzzleRunner object "runner"
    runner.runAll(); // runs through all the puzzles
    return 0; // end program
}
